+        (80.0, 39.0),                // nut top, 40 long
+        (front - (fr - 39.0), 39.0), // body up to the flare foot
+        (front, fr),                 // the flange front
+        (gauge - 3.2, fr),           // 15.9 thick
+        (gauge - 3.2, sr),           // the standoff
+        (gauge, sr),
+        (gauge, 0.0), // the gauge line
